"""The terminal's benchmarks: cpu-z, gpu-z and spec.

All three measure on the device, now, through native code compiled into the
app — CodeBench/Bench/*.c for the CPU (reached through ctypes.CDLL(None),
which releases the GIL for every call, so N threads are N cores) and
CodeBench/GPUBench.swift for the GPU (Metal, timed by the GPU itself). In a
build without those entry points cpu-z and gpu-z fall back to the shell's
older Python measurements (offlinai_shell._cpuz_legacy / _gpuz_legacy).

`spec` runs CodeBench's own workloads of the kinds SPEC CPU 2017 and SPEC CPU
2026 are made of. It is not SPEC: none of SPEC's code, inputs or reference
times are in it, and its ratios are not SPEC results.
"""

import ctypes
import json
import math
import os
import platform
import sys
import threading
import time

# ── The native entry points ─────────────────────────────────────────────


class _Result(ctypes.Structure):
    """cb_bench_result (CodeBench/Bench/cb_bench.h)."""
    _fields_ = [("checksum", ctypes.c_uint64), ("value", ctypes.c_double),
                ("work", ctypes.c_double), ("unit", ctypes.c_char_p)]


_NATIVE = None


def native():
    """The app's benchmark functions, or None in a build without them."""
    global _NATIVE
    if _NATIVE is not None:
        return _NATIVE or None
    try:
        lib = ctypes.CDLL(None)
        lib.cb_spec_count.restype = ctypes.c_int
        lib.cb_spec_id.restype = ctypes.c_char_p
        lib.cb_spec_id.argtypes = [ctypes.c_int]
        lib.cb_spec_run.restype = ctypes.c_int
        lib.cb_spec_run.argtypes = [ctypes.c_char_p, ctypes.c_int, ctypes.POINTER(_Result)]
        lib.cb_cpu_clock_ghz.restype = ctypes.c_double
        lib.cb_cpu_clock_ghz.argtypes = [ctypes.c_int]
        lib.cb_cpu_fma_gflops.restype = ctypes.c_double
        lib.cb_cpu_fma_gflops.argtypes = [ctypes.c_int, ctypes.c_int]
        lib.cb_cpu_triad_gbs.restype = ctypes.c_double
        lib.cb_cpu_triad_gbs.argtypes = [ctypes.c_int, ctypes.c_int]
        lib.cb_cpu_latency_ns.restype = ctypes.c_double
        lib.cb_cpu_latency_ns.argtypes = [ctypes.c_int, ctypes.c_int]
        lib.cb_gpu_info_json.restype = ctypes.c_int
        lib.cb_gpu_info_json.argtypes = [ctypes.c_char_p, ctypes.c_int]
        lib.cb_gpu_fma_tflops.restype = ctypes.c_double
        lib.cb_gpu_fma_tflops.argtypes = [ctypes.c_int, ctypes.c_int]
        lib.cb_gpu_bandwidth_gbs.restype = ctypes.c_double
        lib.cb_gpu_bandwidth_gbs.argtypes = [ctypes.c_int, ctypes.c_int]
        lib.cb_gpu_matmul_gflops.restype = ctypes.c_double
        lib.cb_gpu_matmul_gflops.argtypes = [ctypes.c_int, ctypes.c_int, ctypes.c_int]
        lib.cb_gpu_blur_mpix.restype = ctypes.c_double
        lib.cb_gpu_blur_mpix.argtypes = [ctypes.c_int]
    except (OSError, AttributeError):
        _NATIVE = False
        return None
    _NATIVE = lib
    return lib


# QoS classes (sys/qos.h), and Darwin's background band (sys/resource.h).
_QOS_USER_INTERACTIVE = 0x21
_PRIO_DARWIN_PROCESS = 4
_PRIO_DARWIN_BG = 0x1000

# The kind of core the benchmark in progress runs on: None (the scheduler's
# choice, performance cores first), "p" or "e". Set by _OnCores.
_CORE = None


class _Boost:
    """The calling thread at user-interactive QoS while a benchmark runs, and
    back to what it was after. The terminal runs commands on a thread whose
    QoS lets the scheduler put it on an efficiency core: measured in the app
    on an M4, cpu-z's single-core work took 1.5 times as long there. On the
    efficiency cores (`--core e`) it leaves the thread as it is."""

    def __enter__(self):
        self.prev = None
        if _CORE == "e":
            return self
        try:
            libc = ctypes.CDLL(None)
            self.prev = libc.qos_class_self()
            libc.pthread_set_qos_class_self_np(_QOS_USER_INTERACTIVE, 0)
        except Exception:
            pass
        return self

    def __exit__(self, *exc):
        if self.prev:
            try:
                ctypes.CDLL(None).pthread_set_qos_class_self_np(self.prev, 0)
            except Exception:
                pass
        return False


def _core_option(argv):
    """`--core p|e` from argv: "p", "e", None when absent; ValueError if neither."""
    value = _option(argv, "--core")
    if value is None:
        return None
    kind = {"p": "p", "perf": "p", "performance": "p",
            "e": "e", "eff": "e", "efficiency": "e"}.get(value.lower())
    if kind is None:
        raise ValueError(f"--core takes p (performance) or e (efficiency), not {value!r}")
    return kind


class _OnCores:
    """Runs what is inside on one kind of core.

    "e": the app goes into Darwin's background band until the end, which the
    scheduler keeps on the efficiency cores. A thread's QoS alone only steers:
    on an M4 a background-QoS thread still ran at 3.95 GHz (a performance
    core), the band at 2.7 GHz. "p" (and no --core): each benchmark thread at
    user-interactive QoS (_Boost), performance cores first."""

    def __init__(self, kind):
        self.kind = kind
        self.ok = True

    def __enter__(self):
        global _CORE
        self.prev = _CORE
        _CORE = self.kind
        if self.kind == "e":
            try:
                self.ok = ctypes.CDLL(None).setpriority(_PRIO_DARWIN_PROCESS, 0, _PRIO_DARWIN_BG) == 0
            except Exception:
                self.ok = False
        return self

    def __exit__(self, *exc):
        global _CORE
        if self.kind == "e":
            try:
                ctypes.CDLL(None).setpriority(_PRIO_DARWIN_PROCESS, 0, 0)
            except Exception:
                pass
        _CORE = self.prev
        return False


def _core_count(info, kind):
    """How many cores of `kind` (None: all of them)."""
    if kind == "p" and info.get("p_cores"):
        return info["p_cores"]
    if kind == "e" and info.get("e_cores"):
        return info["e_cores"]
    return info["cores"]


def _core_name(kind, n=1):
    return {"p": "performance core", "e": "efficiency core"}.get(kind, "core") + ("s" if n != 1 else "")


def _columns():
    try:
        import shutil
        return shutil.get_terminal_size().columns
    except Exception:
        return 80


def run_workload(lib, wid, size):
    """One copy of workload `wid` at `size`: (seconds, result) or (None, code)."""
    out = _Result()
    t0 = time.perf_counter()
    rc = lib.cb_spec_run(wid.encode(), size, ctypes.byref(out))
    dt = time.perf_counter() - t0
    return (dt, out) if rc == 0 else (None, rc)


def run_copies(lib, wid, size, copies):
    """`copies` copies of `wid` at once, one thread each: the wall time
    until the last ends, and every copy's result."""
    results = [None] * copies
    gate = threading.Barrier(copies + 1)

    def one(k):
        with _Boost():
            gate.wait()
            results[k] = run_workload(lib, wid, size)

    threads = [threading.Thread(target=one, args=(k,), daemon=True) for k in range(copies)]
    for t in threads:
        t.start()
    gate.wait()
    t0 = time.perf_counter()
    for t in threads:
        t.join()
    return time.perf_counter() - t0, results


# ── The device ──────────────────────────────────────────────────────────


def sysctl(name, text=False):
    """A sysctl by name, as an int (or a string), or None."""
    try:
        libc = ctypes.CDLL(None)
        size = ctypes.c_size_t(0)
        key = name.encode()
        if libc.sysctlbyname(key, None, ctypes.byref(size), None, 0) != 0 or size.value == 0:
            return None
        buf = ctypes.create_string_buffer(size.value)
        if libc.sysctlbyname(key, buf, ctypes.byref(size), None, 0) != 0:
            return None
        if text:
            return buf.value.decode(errors="replace")
        return int.from_bytes(buf.raw[:size.value], "little")
    except Exception:
        return None


# The Arm features worth naming, as the kernel reports them
# (hw.optional.arm.FEAT_*), in the order an architecture manual lists them.
_ARM_FEATURES = ["AES", "PMULL", "SHA1", "SHA256", "SHA512", "SHA3", "CRC32", "LSE", "LSE2",
                 "RDM", "FP16", "FHM", "DotProd", "I8MM", "BF16", "EBF16", "FCMA", "JSCVT",
                 "FRINTTS", "LRCPC", "LRCPC2", "DPB", "DPB2", "SB", "SSBS", "BTI", "PAuth",
                 "PAuth2", "CSSC", "WFxT", "AFP", "RPRES", "SME", "SME2", "SME_F64F64",
                 "SME_I16I64", "SVE"]


def cpu_info():
    """What the kernel says about the cores, caches, memory and features."""
    info = {"cores": os.cpu_count() or 0}
    p = sysctl("hw.perflevel0.physicalcpu")
    e = sysctl("hw.perflevel1.physicalcpu")
    if p:
        info["p_cores"] = p
        info["e_cores"] = e or 0
    for level, key in (("perflevel0", "p"), ("perflevel1", "e")):
        for cache in ("l1icachesize", "l1dcachesize", "l2cachesize"):
            v = sysctl(f"hw.{level}.{cache}")
            if v:
                info[f"{key}_{cache}"] = v
    for key, name in (("line", "hw.cachelinesize"), ("page", "hw.pagesize"),
                      ("memory", "hw.memsize")):
        v = sysctl(name)
        if v:
            info[key] = v
    feats = [f for f in _ARM_FEATURES if sysctl(f"hw.optional.arm.FEAT_{f}") == 1]
    if feats:
        info["features"] = feats
    return info


def device_line():
    """("iPad Air 11-inch (M3)", "Apple M3"), from the shell's table."""
    try:
        from offlinai_shell import _apple_device_info
        return _apple_device_info()
    except Exception:
        return platform.machine(), "unknown chip"


def _kb(n):
    return f"{n // (1 << 20)} MB" if n >= (1 << 20) else f"{n // 1024} KB"


def _colors():
    from offlinai_shell import BOLD, DIM, RED, GRN, YLW, CYN, WHT, RESET
    return BOLD, DIM, RED, GRN, YLW, CYN, WHT, RESET


def _bar(frac, width=24):
    _, DIM, _, GRN, _, _, _, RESET = _colors()
    n = max(0, min(width, int(round(frac * width))))
    return f"{GRN}{'█' * n}{DIM}{'░' * (width - n)}{RESET}"


def _status(text):
    sys.stdout.write(f"\r  {text}\033[K")
    sys.stdout.flush()


# Where results are saved: in the Workspace, so My work and the Files app
# list them (they show only what is under ~/Documents/Workspace).
_RESULTS_DIR = "~/Documents/Workspace/Benchmarks"


def _results_dir():
    root = os.path.expanduser(_RESULTS_DIR)
    os.makedirs(root, exist_ok=True)
    return root


def _save_json(kind, data, path=None):
    """Writes `data` to `path`, or to Workspace/Benchmarks/<kind>-<time>.json."""
    if not path:
        path = os.path.join(_results_dir(), f"{kind}-{time.strftime('%Y-%m-%d-%H%M%S')}.json")
    with open(path, "w") as f:
        json.dump(data, f, indent=2, sort_keys=True)
    return path


def _option(argv, name, default=None):
    """`--name value` or `--name=value` from argv."""
    for i, a in enumerate(argv):
        if a == name and i + 1 < len(argv) and not argv[i + 1].startswith("-"):
            return argv[i + 1]
        if a.startswith(name + "="):
            return a.split("=", 1)[1]
    return default


def _si(x):
    """1234567 -> '1.23 M', for a throughput column."""
    for scale, prefix in ((1e9, "G"), (1e6, "M"), (1e3, "k")):
        if x >= scale:
            return f"{x / scale:.2f} {prefix}"
    return f"{x:.1f}"


def _geomean(values):
    values = [v for v in values if v and v > 0]
    return math.exp(sum(math.log(v) for v in values) / len(values)) if values else 0.0


def _run_on_cores(fn, sh, argv, command):
    """`fn(sh, argv)` on the kind of core `--core` asks for (see _OnCores)."""
    try:
        kind = _core_option(argv)
    except ValueError as e:
        _, _, RED, _, _, _, _, RESET = _colors()
        print(f"{RED}{command}:{RESET} {e}")
        return
    with _OnCores(kind) as on, _Boost():
        if not on.ok:
            _, DIM, _, _, YLW, _, _, RESET = _colors()
            print(f"{YLW}{command}:{RESET} this system wouldn't keep the app on its efficiency "
                  f"cores {DIM}— running where the scheduler puts it{RESET}")
        return fn(sh, argv)


# ── graphs ──────────────────────────────────────────────────────────────

_GRAPH_FORMATS = ("html", "png", "jpg", "jpeg", "svg", "pdf")


def _short(path):
    """`~/Documents/…` rather than the container path (on a Mac it names
    the user); the app's result-line reader expands the `~` again."""
    home = os.path.expanduser("~")
    for p, h in ((path, home), (os.path.realpath(path), os.path.realpath(home))):
        if h and p.startswith(h + os.sep):
            return "~" + p[len(h):]
    return path


def _graph_path(kind, argv):
    """--out as a format (html, png, jpg, svg, pdf) or a file; by default
    an HTML page in Workspace/Benchmarks."""
    out = _option(argv, "--out") or "html"
    fmt = out.lower().lstrip(".")
    if fmt in _GRAPH_FORMATS:
        return os.path.join(_results_dir(), f"{kind}-{time.strftime('%Y-%m-%d-%H%M%S')}.{fmt}")
    path = os.path.abspath(os.path.expanduser(out))
    if os.path.splitext(path)[1].lower().lstrip(".") not in _GRAPH_FORMATS:
        path += ".html"
    os.makedirs(os.path.dirname(path), exist_ok=True)
    return path


# A graph is described once and drawn by plotly (HTML: hover values, zoom,
# legend toggles — the kind of page the app's charts are) or by matplotlib
# (png, jpg, svg, pdf). Each panel:
#   {"title", "xlabel", "ylabel", "xlog": bool, "ylog": bool,
#    "xticks": [(value, label)], "series": [{"name", "x", "y", "color",
#    "marker", "unit"}], "vlines": [(x, label)], "bars": {"labels",
#    "values", "colors", "unit"}}

_PAGE_STYLE = """
:root { color-scheme: light dark; --bg: #f5f6f8; --card: #ffffff; --text: #1c1f24;
        --muted: #5d6573; --line: #e2e5ea; }
@media (prefers-color-scheme: dark) {
  :root { --bg: #0e1014; --card: #171a20; --text: #e7eaef; --muted: #9aa2ad; --line: #2a2f37; }
}
* { box-sizing: border-box; }
body { margin: 0; background: var(--bg); color: var(--text);
       font: 15px/1.45 -apple-system, BlinkMacSystemFont, "Helvetica Neue", Arial, sans-serif; }
main { max-width: 1040px; margin: 0 auto; padding: 20px 16px 28px; }
h1 { font-size: 22px; font-weight: 650; margin: 0; letter-spacing: -0.01em; }
header p { margin: 2px 0 0; color: var(--muted); font-size: 13px; }
.stats { display: grid; grid-template-columns: repeat(auto-fit, minmax(128px, 1fr));
         gap: 10px; margin: 16px 0 4px; }
.stat { background: var(--card); border: 1px solid var(--line); border-radius: 12px;
        padding: 10px 12px; }
.stat b { display: block; font-size: 20px; font-weight: 650; font-variant-numeric: tabular-nums; }
.stat span { font-size: 12px; color: var(--muted); }
section.chart { background: var(--card); border: 1px solid var(--line); border-radius: 14px;
                margin-top: 12px; padding: 12px 8px 4px; }
section.chart h2 { font-size: 15px; font-weight: 600; margin: 0 8px 2px; }
section.chart p { font-size: 12px; color: var(--muted); margin: 0 8px; }
footer { margin-top: 14px; font-size: 12px; color: var(--muted); }
/* The app's preview fits a page with a chart to the pane (html and body at
   100% with no scrolling, every plotly div at 100% high) — right for one
   chart, but it folds these cards flat. More specific rules keep the page. */
html:root, html:root > body { height: auto !important; overflow: auto !important;
                              background: var(--bg) !important; }
main section.chart .plotly-graph-div { height: 340px !important; }
"""

# Light chart colours are set in the figure; in dark mode the page swaps
# these after drawing (plotly has no colour-scheme media query of its own).
_PAGE_SCRIPT = r"""
(function () {
  if (!window.matchMedia || !matchMedia("(prefers-color-scheme: dark)").matches) return;
  var grid = "#2a2f37", text = "#c9ced6";
  document.querySelectorAll(".plotly-graph-div").forEach(function (d) {
    var u = {"font.color": text, "legend.font.color": text, "hoverlabel.bgcolor": "#20242b"};
    Object.keys(d.layout || {}).forEach(function (k) {
      if (/^[xy]axis\d*$/.test(k)) {
        u[k + ".gridcolor"] = grid; u[k + ".linecolor"] = grid; u[k + ".zerolinecolor"] = grid;
      }
    });
    Plotly.relayout(d, u);
  });
})();
"""


def _graph_html(title, panels, path, stats=()):
    """A page of its own: the device as a header, the key numbers as tiles,
    a card per chart (plotly, offline — plotly.js is in the page), light or
    dark with the system."""
    import html
    import plotly.graph_objects as go
    head, _, sub = title.partition(" — ")
    symbols = {"o": "circle", "s": "square"}
    cards = []
    for i, p in enumerate(panels):
        fig = go.Figure()
        series = p.get("series", ())
        for sr in series:
            fig.add_trace(go.Scatter(
                x=sr["x"], y=sr["y"], name=sr["name"], mode="lines+markers",
                line=dict(color=sr["color"], width=2.5), showlegend=len(series) > 1,
                marker=dict(symbol=symbols.get(sr.get("marker", "o"), "circle"), size=7),
                hovertemplate=f"%{{y:.3~g}} {sr.get('unit', '')}<extra>{sr['name']}</extra>"))
        bars = p.get("bars")
        if bars:
            fig.add_trace(go.Bar(x=bars["labels"], y=bars["values"], marker_color=bars["colors"],
                                 text=[f"{v:.2f}" for v in bars["values"]], textposition="outside",
                                 showlegend=False, cliponaxis=False,
                                 hovertemplate=f"%{{y:.3~g}} {bars.get('unit', '')}<extra>%{{x}}</extra>"))
        # Marker lines as traces, in data units: a shape on a log axis takes
        # log10(x) and its label doesn't follow, so neither lands right.
        ys = [y for sr in series for y in sr["y"] if y]
        for x, label in p.get("vlines", ()):
            if ys:
                lo, hi = min(ys), max(ys)
                mid = math.sqrt(lo * hi) if p.get("ylog") else (lo + hi) / 2
                fig.add_trace(go.Scatter(
                    x=[x, x, x], y=[lo, mid, hi], mode="lines+text", text=["", f" {label}", ""],
                    textposition="middle right", textfont=dict(color="#8a919c"),
                    line=dict(color="#a0a6b0", dash="dash", width=1),
                    showlegend=False, hoverinfo="skip"))
        xaxis = dict(title_text=p.get("xlabel", ""), gridcolor="#e8ebef", linecolor="#d4d8de",
                     zerolinecolor="#e8ebef")
        if p.get("xlog"):
            xaxis["type"] = "log"
        if p.get("xticks"):
            xaxis.update(tickvals=[v for v, _ in p["xticks"]], ticktext=[t for _, t in p["xticks"]])
        fig.update_xaxes(**xaxis)
        fig.update_yaxes(title_text=p.get("ylabel", ""), type="log" if p.get("ylog") else None,
                         dtick="D2" if p.get("ylog") else None,     # 1, 2, 5 in each decade
                         gridcolor="#e8ebef", linecolor="#d4d8de", zerolinecolor="#e8ebef")
        fig.update_layout(height=340, margin=dict(l=56, r=18, t=12, b=48),
                          paper_bgcolor="rgba(0,0,0,0)", plot_bgcolor="rgba(0,0,0,0)",
                          font=dict(family="-apple-system, Helvetica Neue, Arial, sans-serif",
                                    size=12, color="#3a404a"),
                          hovermode="x unified" if series else "closest",
                          legend=dict(orientation="h", yanchor="bottom", y=1.0, x=0))
        div = fig.to_html(full_html=False, include_plotlyjs=(i == 0),
                          config={"responsive": True, "displaylogo": False,
                                  "modeBarButtonsToRemove": ["lasso2d", "select2d"]})
        note = f"<p>{html.escape(p['note'])}</p>" if p.get("note") else ""
        cards.append(f'<section class="chart"><h2>{html.escape(p["title"])}</h2>{note}{div}</section>')
    tiles = "".join(f'<div class="stat"><b>{html.escape(v)}</b><span>{html.escape(k)}</span></div>'
                    for k, v in stats)
    page = (f'<!doctype html><html lang="en"><head><meta charset="utf-8">'
            f'<meta name="viewport" content="width=device-width, initial-scale=1">'
            f'<title>{html.escape(head)}</title><style>{_PAGE_STYLE}</style></head><body><main>'
            f'<header><h1>{html.escape(head)}</h1><p>{html.escape(sub)} · '
            f'{time.strftime("%Y-%m-%d %H:%M")}</p></header>'
            + (f'<div class="stats">{tiles}</div>' if tiles else "")
            + "".join(cards)
            + '<footer>Hover a line for its values; drag to zoom, double-tap to reset.</footer>'
            f'</main><script>{_PAGE_SCRIPT}</script></body></html>')
    with open(path, "w", encoding="utf-8") as f:
        f.write(page)


def _graph_image(title, panels, path):
    from matplotlib.figure import Figure
    from matplotlib.backends.backend_agg import FigureCanvasAgg
    fig = Figure(figsize=(9, 4.2 * len(panels) + 0.4), layout="constrained")
    FigureCanvasAgg(fig)          # no pyplot: the app's plt.show hooks stay out of it
    fig.suptitle(title)
    for i, p in enumerate(panels):
        ax = fig.add_subplot(len(panels), 1, i + 1)
        for sr in p.get("series", ()):
            ax.plot(sr["x"], sr["y"], marker=sr.get("marker", "o"), color=sr["color"], label=sr["name"])
        bars = p.get("bars")
        if bars:
            ax.bar(bars["labels"], bars["values"], color=bars["colors"])
        if p.get("xlog"):
            ax.set_xscale("log", base=2)
        if p.get("ylog"):
            ax.set_yscale("log")
        if p.get("xticks"):
            ax.set_xticks([v for v, _ in p["xticks"]])
            ax.set_xticklabels([t for _, t in p["xticks"]])
            ax.minorticks_off()
        top = max((max(sr["y"]) for sr in p.get("series", ()) if sr["y"]), default=1)
        for x, label in p.get("vlines", ()):
            ax.axvline(x, color="#999999", linestyle="--", linewidth=1)
            ax.text(x, top, f" {label}", color="#666666", va="top")
        ax.set_title(p["title"])
        ax.set_xlabel(p.get("xlabel", ""))
        ax.set_ylabel(p.get("ylabel", ""))
        if p.get("series"):
            ax.legend()
    fig.savefig(path, dpi=144, bbox_inches="tight")


def _save_graph(title, panels, path, stats=()):
    """Draws the panels to `path`: HTML by plotly, other formats by
    matplotlib. Returns the file written — a PNG of the same name if plotly
    isn't there."""
    if path.lower().endswith(".html"):
        try:
            _graph_html(title, panels, path, stats)
            return path
        except ImportError:
            path = path[:-len(".html")] + ".png"
    _graph_image(title, panels, path)
    return path


def _size_ticks(kbs):
    """Tick (value, label) pairs for sizes in kilobytes, every other one
    when there are many."""
    ticks = kbs[::2] if len(kbs) > 9 else kbs
    return [(kb, _size_label(kb)) for kb in ticks]


def _announce_graph(path):
    """Says where the graph is — the file, and where My work and the Files
    app list it; the app turns the "[plot saved]" line after it into
    "✓ … ready" and opens the graph."""
    BOLD, DIM, _, _, _, CYN, _, RESET = _colors()
    sys.stdout.write(f"  {BOLD}Saved{RESET}      {CYN}{_short(path)}{RESET}\n")
    if os.path.dirname(os.path.realpath(path)) == os.path.realpath(_results_dir()):
        sys.stdout.write(f"  {DIM}           in My work and the Files app: Workspace › Benchmarks{RESET}\n")
    print(f"[plot saved] {_short(path)}", flush=True)


def _size_label(kb):
    return f"{kb // 1024} MB" if kb >= 1024 else f"{kb} KB"


# ── cpu-z ───────────────────────────────────────────────────────────────

# The workloads cpu-z scores, at size 1 (about a quarter of a second each
# on an M4): two integer, one compression, one floating point.
_CPUZ_WORKLOADS = ("compile", "chess", "lzfast", "raytrace")

# Their single-copy seconds on one performance core of the reference, a
# Mac mini M4 (Mac16,10) running the iPad app, optimised build — set from
# its own runs.
_CPUZ_REF = {
    "compile": 0.204,
    "chess": 0.214,
    "lzfast": 0.222,
    "raytrace": 0.203,
}

# The CPU-Z bench (v17) scale the scores are estimated on, as before: an
# Apple M4 core posts about 800–830 single-threaded in CPU-Z, so one M4
# performance core of work is 815 here. Multi-threaded is the same unit
# times how many M4 performance cores' worth of work all the cores did
# together (CPU-Z's multi-threaded score grows nearly linearly with cores).
# An estimate from CodeBench's own workloads, not CPUID's.
_CPUZ_M4_CORE = 815


def cpuz(sh, argv):
    return _run_on_cores(_cpuz, sh, argv, "cpu-z")


def _cpuz(sh, argv):
    """cpu-z — the CPU: cores, caches, features and measured performance.

    Everything below the device lines is measured now, in native code:
    the performance cores' clock, one core's and all cores' FP32/FP64
    fused multiply-add throughput, memory bandwidth (STREAM triad) and
    latency (L1, L2, DRAM), and four real workloads (a compiler, a chess
    search, compression, a ray tracer) on one core and on all of them.

    Usage:
      cpu-z [graph [latency|bandwidth|fma]] [--core p|e] [-i] [-q]
            [--stress S] [--out FORMAT|PATH] [--json [P]]

    Options:
      graph      draw it instead: memory latency under random access
                 against block size, bandwidth against array size, FMA
                 throughput against threads — all three, or the one named
                 (`cpu-z graph latency`); an HTML page (plotly) by default
      --out F    the graph as html (default), png, jpg, svg or pdf, or to a
                 file path
      --core p   performance cores only; --core e efficiency cores only
                 (the frequency itself can't be set on iOS)
      -i         information only, no benchmark
      -q         shorter runs (noisier)
      --stress S all cores for S seconds, the score every second
                 (shows throttling as the device warms)
      --json [P] also save the results as JSON (to P, or Workspace/Benchmarks)
    """
    lib = native()
    if lib is None:
        from offlinai_shell import _cpuz_legacy
        return _cpuz_legacy(sh, argv)
    BOLD, DIM, RED, GRN, YLW, CYN, WHT, RESET = _colors()
    w = sys.stdout.write
    quick = "-q" in argv
    ms = 120 if quick else 300
    product, chip = device_line()
    info = cpu_info()
    kind = _CORE
    cores = _core_count(info, kind)
    report = {"device": product, "chip": chip, "machine": platform.machine(), "info": info,
              "cores_used": kind or "all", "when": time.strftime("%Y-%m-%d %H:%M:%S")}

    w(f"\n{BOLD}CPU-Z{RESET}  {DIM}CodeBench edition — measured live in native code{RESET}\n")
    w(f"{DIM}{'─' * 64}{RESET}\n")
    w(f"  {BOLD}Device    {RESET}{CYN}{product}{RESET}  {DIM}({platform.machine()}){RESET}\n")
    w(f"  {BOLD}Chip      {RESET}{CYN}{chip}{RESET}\n")
    if "p_cores" in info:
        w(f"  {BOLD}Cores     {RESET}{cores} = {info['p_cores']} performance + "
          f"{info['e_cores']} efficiency\n")
    else:
        w(f"  {BOLD}Cores     {RESET}{cores}\n")
    for key, label in (("p", "P caches  "), ("e", "E caches  ")):
        parts = []
        if f"{key}_l1icachesize" in info:
            parts.append(f"L1 {_kb(info[f'{key}_l1icachesize'])} I + "
                         f"{_kb(info[f'{key}_l1dcachesize'])} D")
        if f"{key}_l2cachesize" in info:
            parts.append(f"L2 {_kb(info[f'{key}_l2cachesize'])}")
        if parts:
            w(f"  {BOLD}{label}{RESET}{' · '.join(parts)}\n")
    if "line" in info:
        w(f"  {BOLD}Memory    {RESET}{info.get('memory', 0) / (1 << 30):.1f} GB · "
          f"{info['line']} B lines · {info.get('page', 0) // 1024} KB pages\n")
    if info.get("features"):
        feats = info["features"]
        w(f"  {BOLD}Features  {RESET}{' '.join(feats[:12])}\n")
        for i in range(12, len(feats), 12):
            w(f"            {' '.join(feats[i:i + 12])}\n")
    w(f"  {BOLD}OS        {RESET}{platform.system()} {platform.release()} · "
      f"Python {platform.python_version()}\n")
    if kind:
        w(f"  {BOLD}Run on    {RESET}{YLW}the {cores} {_core_name(kind, cores)} only{RESET}\n")
    w(f"{DIM}{'─' * 64}{RESET}\n")
    sys.stdout.flush()
    if "-i" in argv:
        return
    if "graph" in argv or _option(argv, "--out") is not None:
        return _cpuz_graph(lib, argv, info, cores, ms)

    stress = _option(argv, "--stress")
    if stress is not None:
        return _cpuz_stress(lib, cores, float(stress or 30))

    def all_cores(fn, *args):
        vals = [0.0] * cores

        def one(k):
            with _Boost():
                vals[k] = fn(*args)
        ts = [threading.Thread(target=one, args=(k,), daemon=True) for k in range(cores)]
        for t in ts:
            t.start()
        for t in ts:
            t.join()
        return sum(vals)

    _status(f"{YLW}measuring{RESET} the clock…")
    ghz = lib.cb_cpu_clock_ghz(ms)
    _status(f"{YLW}measuring{RESET} FP32 and FP64 throughput…")
    f32 = lib.cb_cpu_fma_gflops(32, ms)
    f64 = lib.cb_cpu_fma_gflops(64, ms)
    f32_all = all_cores(lib.cb_cpu_fma_gflops, 32, ms)
    f64_all = all_cores(lib.cb_cpu_fma_gflops, 64, ms)
    _status(f"{YLW}measuring{RESET} memory bandwidth…")
    triad = lib.cb_cpu_triad_gbs(64, ms)
    triad_all = all_cores(lib.cb_cpu_triad_gbs, 32, ms)
    _status(f"{YLW}measuring{RESET} memory latency…")
    lat = {"L1": lib.cb_cpu_latency_ns(16, ms // 2),
           "L2": lib.cb_cpu_latency_ns(2048, ms // 2),
           "DRAM": lib.cb_cpu_latency_ns(256 * 1024, ms)}

    work = []
    for wid in _CPUZ_WORKLOADS:
        _status(f"{YLW}running{RESET} {wid} on one core…")
        single, res = run_workload(lib, wid, 1)
        _status(f"{YLW}running{RESET} {wid} on {cores} cores…")
        wall, _ = run_copies(lib, wid, 1, cores)
        work.append((wid, single, wall))
    _status("")
    w("\r\033[K")

    every = f"all {cores} {kind.upper() + ' ' if kind else ''}cores"
    w(f"  {BOLD}{'':<16}{'one core':>14}{every:>18}{RESET}\n")
    if ghz:
        w(f"  {'Clock':<16}{WHT}{ghz:>10.2f} GHz{RESET}  "
          f"{DIM}({'an efficiency' if kind == 'e' else 'a performance'} core){RESET}\n")
    w(f"  {'FP32 FMA':<16}{WHT}{f32:>9.0f} GFLOPS{f32_all:>12.0f} GFLOPS{RESET}\n")
    w(f"  {'FP64 FMA':<16}{WHT}{f64:>9.0f} GFLOPS{f64_all:>12.0f} GFLOPS{RESET}\n")
    w(f"  {'Memory triad':<16}{WHT}{triad:>10.1f} GB/s{triad_all:>13.1f} GB/s{RESET}\n")
    w(f"  {'Latency':<16}{WHT}L1 {lat['L1']:.2f} ns · L2 {lat['L2']:.1f} ns · "
      f"DRAM {lat['DRAM']:.0f} ns{RESET}\n")
    w(f"  {BOLD}Workloads{RESET}\n")
    singles, multis = [], []
    for wid, single, wall in work:
        ref = _CPUZ_REF.get(wid)
        if single and ref:
            singles.append(ref / single)
            multis.append(cores * ref / wall)
        w(f"    {wid:<12}{WHT}{(single or 0) * 1e3:>10.0f} ms{(wall or 0) * 1e3:>14.0f} ms{RESET}"
          f"  {DIM}({cores} copies){RESET}\n")
    w(f"{DIM}{'─' * 64}{RESET}\n")
    report.update({"clock_ghz": ghz, "fp32_gflops": [f32, f32_all], "fp64_gflops": [f64, f64_all],
                   "triad_gbs": [triad, triad_all], "latency_ns": lat,
                   "workloads": {wid: {"single_s": s, "all_cores_wall_s": m, "copies": cores}
                                 for wid, s, m in work}})
    if singles:
        s_score = int(round(_CPUZ_M4_CORE * _geomean(singles)))
        m_score = int(round(_CPUZ_M4_CORE * _geomean(multis)))
        report["score"] = {"single": s_score, "multi": m_score,
                           "m4_cores_equivalent": _geomean(multis)}
        w(f"  {BOLD}CPU score{RESET}   single {GRN}{BOLD}{s_score}{RESET} · multi "
          f"{GRN}{BOLD}{m_score}{RESET}\n")
        w(f"  {DIM}≈ CPU-Z v17 bench scale, est. — Apple M4 ≈ {_CPUZ_M4_CORE} single;\n"
          f"  multi = {_geomean(multis):.1f} M4 performance cores' work{RESET}\n")
    if "--json" in argv or any(a.startswith("--json=") for a in argv):
        path = _save_json("cpu-z", report, _option(argv, "--json"))
        w(f"  {DIM}saved {path}{RESET}\n")
    w("\n")
    sys.stdout.flush()


_CPUZ_GRAPHS = ("latency", "bandwidth", "fma")


def _cpuz_graph(lib, argv, info, cores, ms):
    """cpu-z graph [latency|bandwidth|fma]: memory latency under random
    access against block size (the cache levels as steps), STREAM triad
    bandwidth against array size, FP32/FP64 FMA throughput against the
    number of threads — all three, or the ones named."""
    BOLD, DIM, RED, GRN, YLW, CYN, WHT, RESET = _colors()
    w = sys.stdout.write
    kind = _CORE
    which = [g for g in _CPUZ_GRAPHS if g in argv] or list(_CPUZ_GRAPHS)
    path = _graph_path("cpu-z-" + (which[0] if len(which) == 1 else "graph"), argv)
    step = max(40, ms // 3)

    lat_kb, lat, bw_mb, bw, threads, fma = [], [], [], [], [], {32: [], 64: []}
    if "latency" in which:
        # 4 KB … 256 MB: doubling, or ×√2 when it is the only graph.
        lat_kb = ([4 << i for i in range(17)] if len(which) > 1 else
                  sorted({int(round(4 * 2 ** (i / 2))) for i in range(33)}))
        for kb in lat_kb:
            _status(f"{YLW}measuring{RESET} random-access latency in {_size_label(kb)}…")
            lat.append(lib.cb_cpu_latency_ns(kb, step))
    if "bandwidth" in which:
        bw_mb = [1 << i for i in range(9)]                   # 1 … 256 MB
        for mb in bw_mb:
            _status(f"{YLW}measuring{RESET} bandwidth over {mb} MB…")
            bw.append(lib.cb_cpu_triad_gbs(mb, step))
    if "fma" in which:
        threads = list(range(1, cores + 1))
        for n in threads:
            _status(f"{YLW}measuring{RESET} FMA throughput on {n} thread{'s' if n > 1 else ''}…")
            for bits in (32, 64):
                vals = [0.0] * n

                def one(k, bits=bits, vals=vals):
                    with _Boost():
                        vals[k] = lib.cb_cpu_fma_gflops(bits, step)
                ts = [threading.Thread(target=one, args=(k,), daemon=True) for k in range(n)]
                for t in ts:
                    t.start()
                for t in ts:
                    t.join()
                fma[bits].append(sum(vals))
    _status("")
    w("\r\033[K")

    product, chip = device_line()
    where = f"{cores} {_core_name(kind, cores)}" if kind else f"{cores} cores"
    pre, core = ("e", "efficiency core") if kind == "e" else ("p", "performance core")
    panels = []
    if lat:
        vlines = [(info[f"{pre}_{key}"] // 1024, f"{name} {_size_label(info[f'{pre}_{key}'] // 1024)}")
                  for key, name in (("l1dcachesize", "L1"), ("l2cachesize", "L2"))
                  if info.get(f"{pre}_{key}")]
        ticks = [kb for kb in lat_kb if kb & (kb - 1) == 0]          # the powers of two
        panels.append({
            "title": f"Random-access memory latency ({core})",
            "note": "Each load waits for the one before: a chase through a block of this "
                    "size in random order. The steps are the caches; the top is main memory.",
            "xlabel": "block size (each load at a random cache line of it)", "ylabel": "ns per load",
            "xlog": True, "ylog": True, "xticks": _size_ticks(ticks), "vlines": vlines,
            "series": [{"name": "load-to-use latency", "x": lat_kb, "y": lat, "color": "#2a6fdb",
                        "marker": "o", "unit": "ns"}]})
    if bw:
        bw_kb = [mb * 1024 for mb in bw_mb]
        panels.append({
            "title": f"Memory bandwidth, STREAM triad (one {core})",
            "note": "a[i] = b[i] + s·c[i] over three arrays of this size, from one thread.",
            "xlabel": "array size (each of three)", "ylabel": "GB/s", "xlog": True,
            "xticks": _size_ticks(bw_kb),
            "series": [{"name": "STREAM triad", "x": bw_kb, "y": bw, "color": "#1b9e77",
                        "marker": "o", "unit": "GB/s"}]})
    if threads:
        panels.append({
            "title": f"FMA throughput against threads ({where})",
            "note": "Fused multiply-adds per second, NEON, every thread busy.",
            "xlabel": "threads", "ylabel": "GFLOPS", "xticks": [(n, str(n)) for n in threads],
            "series": [{"name": "FP32", "x": threads, "y": fma[32], "color": "#d95f02",
                        "marker": "o", "unit": "GFLOPS"},
                       {"name": "FP64", "x": threads, "y": fma[64], "color": "#7570b3",
                        "marker": "s", "unit": "GFLOPS"}]})
    stats = []
    if lat:
        stats += [("L1 latency", f"{min(lat):.2f} ns"), ("memory latency", f"{lat[-1]:.0f} ns")]
    if bw:
        stats += [("bandwidth, one core", f"{max(bw):.0f} GB/s")]
    if threads:
        stats += [("FP32, all threads", f"{fma[32][-1]:.0f} GFLOPS"),
                  ("FP64, all threads", f"{fma[64][-1]:.0f} GFLOPS")]
    written = _save_graph(f"{chip} · {product} — CPU, measured in CodeBench", panels, path, stats)

    if lat:
        w(f"  {BOLD}Latency{RESET}    " + " · ".join(
            f"{_size_label(kb)} {ns:.1f} ns" for kb, ns in zip(lat_kb, lat)
            if kb in (16, 1024, 8192, 262144)) + "\n")
    if bw:
        w(f"  {BOLD}Bandwidth{RESET}  " + " · ".join(
            f"{mb} MB {gbs:.0f} GB/s" for mb, gbs in zip(bw_mb, bw) if mb in (1, 16, 256)) + "\n")
    if threads:
        w(f"  {BOLD}FMA{RESET}        FP32 {fma[32][0]:.0f} → {fma[32][-1]:.0f} GFLOPS, "
          f"FP64 {fma[64][0]:.0f} → {fma[64][-1]:.0f} GFLOPS (1 → {cores} threads)\n")
    _announce_graph(written)
    if "--json" in argv or any(a.startswith("--json=") for a in argv):
        data = {"device": product, "chip": chip, "cores_used": kind or "all"}
        if lat:
            data["latency_ns"] = dict(zip(map(str, lat_kb), lat))
        if bw:
            data["triad_gbs"] = dict(zip(map(str, bw_mb), bw))
        if threads:
            data["fma_gflops"] = {"threads": threads, "fp32": fma[32], "fp64": fma[64]}
        w(f"  {DIM}saved {_short(_save_json('cpu-z-graph', data, _option(argv, '--json')))}{RESET}\n")
    w("\n")
    sys.stdout.flush()


def _cpuz_stress(lib, cores, seconds):
    """All cores on the workloads for `seconds`, the work done each second."""
    BOLD, DIM, RED, GRN, YLW, CYN, WHT, RESET = _colors()
    w = sys.stdout.write
    stop = time.perf_counter() + seconds
    done = [0] * cores
    lock = threading.Lock()

    def worker(k):
        _Boost().__enter__()          # a thread of its own, ended with the stress run
        i = k
        while time.perf_counter() < stop:
            dt, _ = run_workload(lib, _CPUZ_WORKLOADS[i % len(_CPUZ_WORKLOADS)], 1)
            i += 1
            with lock:
                done[k] += 1
    ts = [threading.Thread(target=worker, args=(k,), daemon=True) for k in range(cores)]
    for t in ts:
        t.start()
    w(f"  {BOLD}Stress{RESET}  {cores} threads for {seconds:.0f} s — workloads finished each second\n")
    first, last, t_prev = None, 0, time.perf_counter()
    try:
        # Seconds wholly before the deadline only: after it, the copies in
        # flight finish one by one, and that tail is not the device slowing.
        while time.perf_counter() + 1.0 <= stop:
            time.sleep(1.0)
            total = sum(done)
            now = time.perf_counter()
            rate = (total - last) / (now - t_prev)
            last, t_prev = total, now
            if rate > 0 and first is None:
                first = rate
            frac = rate / first if first else 0
            w(f"    {int(seconds - max(0, stop - now)):>4} s  {WHT}{rate:6.1f}/s{RESET}  "
              f"{_bar(min(1.2, frac) / 1.2)}  {DIM}{frac * 100:5.0f}% of the first second{RESET}\n")
            sys.stdout.flush()
    except KeyboardInterrupt:
        stop = 0
    w(f"  {DIM}finishing the workloads in flight…{RESET}\n")
    for t in ts:
        t.join()
    w("\n")


# ── gpu-z ───────────────────────────────────────────────────────────────

# This Mac mini M4's GPU (10 cores), the reference the score is relative to:
# FP32 TFLOPS, GB/s, MPS fp32 matmul GFLOPS, blur Mpix/s — set from its runs.
_GPUZ_REF = {
    "fp32": 3.55,
    "bw": 92.5,
    "mm32": 2.93,
    "blur": 2245,
}

# Geekbench 6 Metal anchor for the same Mac mini M4 (≈ 57,000).
_GB6_GPU_M4 = 57000


def gpuz(sh, argv):
    with _Boost():
        return _gpuz(sh, argv)


def _gpuz(sh, argv):
    """gpu-z — the GPU: what Metal reports, and measured performance.

    The benchmarks run on Metal directly and are timed by the GPU itself,
    so no copy to or from the CPU is in them: peak FP32 and FP16 shader
    arithmetic, memory bandwidth, MPS matrix multiply (fp32 and fp16, 4096²)
    and a 4096² Gaussian blur. About five seconds; no torch import.

    Usage:
      gpu-z [graph] [-i] [-q] [--torch] [--out FORMAT|PATH] [--json [P]]

    Options:
      graph      draw it instead: matrix-multiply TFLOPS against matrix
                 size (fp32, fp16), bandwidth against buffer size, and peak
                 shader TFLOPS — an HTML page (plotly) by default
      --out F    the graph as html (default), png, jpg, svg or pdf, or to a
                 file path
      -i         information only, no benchmark
      -q         shorter runs (noisier)
      --torch    also time PyTorch's Metal bridge (what Python code gets,
                 copies included; the first run imports torch)
      --json [P] also save the results as JSON (to P, or Workspace/Benchmarks)
    """
    lib = native()
    BOLD, DIM, RED, GRN, YLW, CYN, WHT, RESET = _colors()
    w = sys.stdout.write
    info = {}
    if lib is not None:
        buf = ctypes.create_string_buffer(8192)
        n = lib.cb_gpu_info_json(buf, len(buf))
        if n > 0:
            info = json.loads(buf.value.decode())
    if lib is None or not info:
        from offlinai_shell import _gpuz_legacy
        return _gpuz_legacy(sh, argv)
    quick = "-q" in argv
    ms = 250 if quick else 400
    product, chip = device_line()
    report = {"device": product, "chip": chip, "info": info, "when": time.strftime("%Y-%m-%d %H:%M:%S")}

    def yes(flag):
        return f"{GRN}yes{RESET}" if flag else f"{DIM}no{RESET}"

    w(f"\n{BOLD}GPU-Z{RESET}  {DIM}CodeBench edition — Metal, measured live{RESET}\n")
    w(f"{DIM}{'─' * 64}{RESET}\n")
    w(f"  {BOLD}GPU       {RESET}{CYN}{info.get('name', chip + ' GPU')}{RESET}\n")
    w(f"  {BOLD}Device    {RESET}{product}\n")
    if info.get("families"):
        # The highest of each kind (supporting Apple9 means Apple1–8 too).
        fams, top = info["families"], {}
        for f in fams:
            kind = f.rstrip("0123456789")
            top[kind] = f
        w(f"  {BOLD}Families  {RESET}{' · '.join(top.values())}\n")
    w(f"  {BOLD}Memory    {RESET}{'unified' if info.get('unified_memory') else 'dedicated'} · "
      f"working set {info.get('budget', 0) / (1 << 30):.1f} GB · largest buffer "
      f"{info.get('max_buffer', 0) / (1 << 30):.1f} GB\n")
    mt = info.get("max_threads_per_group", [0, 0, 0])
    w(f"  {BOLD}Threads   {RESET}{mt[0]} a group · {info.get('threadgroup_memory', 0) // 1024} KB "
      f"threadgroup memory\n")
    feats = [("ray tracing", yes(info.get("raytracing"))),
             ("function pointers", yes(info.get("function_pointers"))),
             ("dynamic libraries", yes(info.get("dynamic_libraries"))),
             ("float32 filtering", yes(info.get("float32_filtering"))),
             ("BC textures", yes(info.get("bc_textures"))),
             ("argument buffers", f"tier {info.get('argument_buffers_tier', '?')}"),
             ("read-write textures", f"tier {info.get('read_write_textures_tier', '?')}")]
    # Two to a line, so the block fits an 80-column terminal.
    for i in range(0, len(feats), 2):
        pair = " · ".join(f"{name} {val}" for name, val in feats[i:i + 2])
        w(f"  {BOLD}{'Features' if i == 0 else '':<10}{RESET}{pair}\n")
    w(f"{DIM}{'─' * 64}{RESET}\n")
    sys.stdout.flush()
    if "-i" in argv:
        return
    if "graph" in argv or _option(argv, "--out") is not None:
        return _gpuz_graph(lib, argv, info, ms)

    _status(f"{YLW}running{RESET} FP32 shader arithmetic…")
    fp32 = lib.cb_gpu_fma_tflops(32, ms)
    _status(f"{YLW}running{RESET} FP16 shader arithmetic…")
    fp16 = lib.cb_gpu_fma_tflops(16, ms)
    _status(f"{YLW}running{RESET} memory bandwidth…")
    bw = lib.cb_gpu_bandwidth_gbs(256, ms)
    _status(f"{YLW}running{RESET} MPS matrix multiply…")
    mm32 = lib.cb_gpu_matmul_gflops(4096, 32, ms)
    mm16 = lib.cb_gpu_matmul_gflops(4096, 16, ms)
    _status(f"{YLW}running{RESET} Gaussian blur…")
    blur = lib.cb_gpu_blur_mpix(ms)
    _status("")
    w("\r\033[K")
    rows = [("FP32 shader FMA", fp32, "TFLOPS", "fp32", 2), ("FP16 shader FMA", fp16, "TFLOPS", None, 2),
            ("Memory bandwidth", bw, "GB/s", "bw", 0), ("Matmul fp32 (MPS)", mm32 / 1000, "TFLOPS", "mm32", 2),
            ("Matmul fp16 (MPS)", mm16 / 1000, "TFLOPS", None, 2), ("Gaussian blur 4K", blur, "Mpix/s", "blur", 0)]
    ratios = []
    for label, value, unit, key, digits in rows:
        ref = _GPUZ_REF.get(key) if key else None
        if ref and value:
            ratios.append(value / ref)
        frac = value / (ref * 1.6) if ref else 0
        w(f"  {label:<20}{WHT}{value:>9.{digits}f} {unit:<7}{RESET}"
          + (f" {_bar(min(1.0, frac))}" if ref else "") + "\n")
    report.update({"fp32_tflops": fp32, "fp16_tflops": fp16, "bandwidth_gbs": bw,
                   "matmul_fp32_gflops": mm32, "matmul_fp16_gflops": mm16, "blur_mpix": blur})
    w(f"{DIM}{'─' * 64}{RESET}\n")
    if ratios:
        score = int(round(_GB6_GPU_M4 * _geomean(ratios)))
        report["score"] = score
        w(f"  {BOLD}GPU score{RESET}   {GRN}{BOLD}{score}{RESET}\n")
        w(f"  {DIM}≈ Geekbench 6 Metal scale, est. — Mac mini M4 ≈ {_GB6_GPU_M4 // 1000}k; "
          f"GPU time only{RESET}\n")
    if "--torch" in argv:
        from offlinai_shell import _gpuz_legacy
        w(f"  {DIM}PyTorch's Metal bridge, copies included:{RESET}\n")
        _gpuz_legacy(sh, [a for a in argv if a != "--torch"] + ["--bench-only"])
    if "--json" in argv or any(a.startswith("--json=") for a in argv):
        path = _save_json("gpu-z", report, _option(argv, "--json"))
        w(f"  {DIM}saved {path}{RESET}\n")
    w("\n")
    sys.stdout.flush()


def _gpuz_graph(lib, argv, info, ms):
    """gpu-z graph: MPS matrix-multiply TFLOPS against matrix size (fp32
    and fp16), memory bandwidth against buffer size, and peak shader
    arithmetic (FP32, FP16) beside the best matrix multiply."""
    BOLD, DIM, RED, GRN, YLW, CYN, WHT, RESET = _colors()
    w = sys.stdout.write
    path = _graph_path("gpu-z-graph", argv)
    step = max(60, ms // 2)

    sizes = [256, 512, 768, 1024, 1536, 2048, 3072, 4096]
    mm = {32: [], 16: []}
    for n in sizes:
        _status(f"{YLW}running{RESET} matrix multiply {n}×{n}…")
        for bits in (32, 16):
            mm[bits].append(lib.cb_gpu_matmul_gflops(n, bits, step) / 1000)
    bw_mb = [1 << i for i in range(9)]                       # 1 … 256 MB
    bw = []
    for mb in bw_mb:
        _status(f"{YLW}running{RESET} bandwidth over {mb} MB…")
        bw.append(lib.cb_gpu_bandwidth_gbs(mb, step))
    _status(f"{YLW}running{RESET} peak shader arithmetic…")
    fp32 = lib.cb_gpu_fma_tflops(32, ms)
    fp16 = lib.cb_gpu_fma_tflops(16, ms)
    _status("")
    w("\r\033[K")

    product, chip = device_line()
    name = info.get("name", chip + " GPU")
    bw_kb = [mb * 1024 for mb in bw_mb]
    panels = [
        {"title": "Matrix multiply (MPS) against size",
         "note": "Two n×n matrices multiplied by Metal Performance Shaders, timed by the GPU.",
         "xlabel": "matrix size n (n×n times n×n)", "ylabel": "TFLOPS", "xlog": True,
         "xticks": [(n, str(n)) for n in sizes],
         "series": [{"name": "fp32", "x": sizes, "y": mm[32], "color": "#2a6fdb",
                     "marker": "o", "unit": "TFLOPS"},
                    {"name": "fp16", "x": sizes, "y": mm[16], "color": "#d95f02",
                     "marker": "s", "unit": "TFLOPS"}]},
        {"title": "Memory bandwidth against buffer size", "xlabel": "buffer size",
         "note": "A copy into a second buffer as large, counted as a read and a write.",
         "ylabel": "GB/s", "xlog": True, "xticks": _size_ticks(bw_kb),
         "series": [{"name": "copy, GPU-timed", "x": bw_kb, "y": bw, "color": "#1b9e77",
                     "marker": "o", "unit": "GB/s"}]},
        {"title": "Peak arithmetic", "ylabel": "TFLOPS",
         "note": "Shader fused multiply-adds beside the best matrix multiply above.",
         "bars": {"labels": ["FP32 shader FMA", "FP16 shader FMA", "fp32 matmul (best)",
                             "fp16 matmul (best)"],
                  "values": [fp32, fp16, max(mm[32]), max(mm[16])],
                  "colors": ["#2a6fdb", "#d95f02", "#7aa6ef", "#f2a26b"], "unit": "TFLOPS"}},
    ]
    stats = [("FP32 shader", f"{fp32:.2f} TFLOPS"), ("FP16 shader", f"{fp16:.2f} TFLOPS"),
             ("matmul fp32, best", f"{max(mm[32]):.2f} TFLOPS"),
             ("bandwidth, 256 MB", f"{bw[-1]:.0f} GB/s")]
    written = _save_graph(f"{name} · {product} — GPU, measured in CodeBench", panels, path, stats)

    w(f"  {BOLD}Matmul{RESET}     fp32 {max(mm[32]):.2f} · fp16 {max(mm[16]):.2f} TFLOPS at best "
      f"(n = {sizes[mm[32].index(max(mm[32]))]})\n")
    w(f"  {BOLD}Bandwidth{RESET}  " + " · ".join(
        f"{mb} MB {gbs:.0f} GB/s" for mb, gbs in zip(bw_mb, bw) if mb in (1, 16, 256)) + "\n")
    w(f"  {BOLD}Shader FMA{RESET} FP32 {fp32:.2f} · FP16 {fp16:.2f} TFLOPS\n")
    _announce_graph(written)
    if "--json" in argv or any(a.startswith("--json=") for a in argv):
        data = {"device": product, "gpu": name,
                "matmul_tflops": {"n": sizes, "fp32": mm[32], "fp16": mm[16]},
                "bandwidth_gbs": dict(zip(map(str, bw_mb), bw)),
                "fma_tflops": {"fp32": fp32, "fp16": fp16}}
        w(f"  {DIM}saved {_short(_save_json('gpu-z-graph', data, _option(argv, '--json')))}{RESET}\n")
    w("\n")
    sys.stdout.flush()


